package mod.cdv.tnpc.tactical;
public class ModelChecks26 {public static class Part {public float xRot,zRot,yRot;public void copyFrom(Part p){xRot=p.xRot;zRot=p.zRot;yRot=p.yRot;}}public static class Model {public Part head=new Part(),hat=new Part();public Part body=new Part(),jacket=new Part(),leftLeg=new Part(),rightLeg=new Part(),leftPants=new Part(),rightPants=new Part(),leftArm=new Part(),rightArm=new Part(),leftSleeve=new Part(),rightSleeve=new Part();}
 public static void main(String[]args){var w=new MotionChecks26.World();var npc=new MotionChecks26.Soldier(w);var fake=new mod.cdv.tnpc.client.FakePlayer(w,npc);Model m=new Model();Client26.SLIDES.put(npc,System.nanoTime()+650_000_000L);var action=new Motion27.Motion();action.slide=System.nanoTime()-200_000_000L;action.end=System.nanoTime()+450_000_000L;Motion27.MOTIONS.put(npc,action);Client26.model(m,fake,0);if(m.body.zRot==0||m.leftLeg.xRot==m.rightLeg.xRot)throw new AssertionError("distinct ground slide pose missing");if(m.leftPants.xRot!=m.leftLeg.xRot||m.rightPants.xRot!=m.rightLeg.xRot||m.jacket.zRot!=m.body.zRot)throw new AssertionError("clothing failed to follow slide");Client26.SLIDES.clear();Motion27.MOTIONS.clear();m=new Model();Client26.FIRES.put(npc,System.nanoTime()-45_000_000L);Client26.model(m,fake,0);if(m.leftArm.xRot>=0||m.rightArm.xRot>=0||m.leftSleeve.xRot!=m.leftArm.xRot||m.rightSleeve.xRot!=m.rightArm.xRot)throw new AssertionError("weapon recoil and clothing must move together");if(!Client26.WARN.isEmpty())throw new AssertionError("silent model API failure");System.out.println("SLIDE_DISTINCT_LEGS_BODY_CLOTHING_AND_SHOT_RECOIL_MODEL_CHECKS=PASS");}}
